  'trucks.detail.addLoad': { ru: '+ груз', en: '+ load', es: '+ carga', uk: '+ вантаж', ro: '+ cursă', kk: '+ жүк' },
  'trucks.detail.onMap': { ru: 'На карте', en: 'On the map', es: 'En el mapa', uk: 'На мапі', ro: 'Pe hartă', kk: 'Картада' },
  'trucks.detail.onMapInfo': {
    ru: 'Где сейчас трак (по GPS из ELD) и куда идёт доставка — точка delivery из активного груза этого трака. Линия и подпись показывают примерное расстояние и время в пути до места выгрузки.',
    en: 'Where the truck is right now (GPS from the ELD) and where the delivery is headed — the delivery point from this truck’s active load. The line and label show the approximate distance and drive time to drop-off.',
    es: 'Dónde está el camión (por GPS del ELD) y adónde va la entrega — el punto de delivery de su carga activa. La línea y la etiqueta muestran la distancia y el tiempo aproximados hasta la descarga.',
    uk: 'Де зараз трак (за GPS з ELD) і куди йде доставка — точка delivery з активного вантажу цього трака. Лінія і підпис показують приблизну відстань і час у дорозі до місця вивантаження.',
    ro: 'Unde e camionul (după GPS-ul din ELD) și încotro merge livrarea — punctul de delivery al cursei active. Linia și eticheta arată distanța și timpul aproximativ până la descărcare.',
    kk: 'Тракт қазір қайда (ELD GPS бойынша) және жеткізу қайда — осы тракттың белсенді жүгіндегі delivery нүктесі. Сызық пен жазу түсіру орнына дейінгі шамамен қашықтық пен уақытты көрсетеді.',
  },
  'trucks.detail.tripHistory': { ru: 'История пути', en: 'Trip history', es: 'Historial del viaje', uk: 'Історія шляху', ro: 'Istoricul cursei', kk: 'Жол тарихы' },
  'trucks.detail.tripHistoryInfo': {
    ru: 'Путь трака по GPS-точкам из ELD, разбитый на движение и стоянки. Остановки короче 30 минут (светофоры, пробки) не показываются — только заметные: погрузка/выгрузка, заправка, отдых. Стоянки от 6 часов подряд помечены как долгий отдых. GPS-история хранится 7 дней.',
    en: 'The truck’s path from ELD GPS points, split into drive legs and stops. Stops under 30 minutes (lights, traffic) aren’t shown — only the ones that matter: loading/unloading, fuel, rest. Stops of 6+ hours are flagged as a long rest. GPS history is kept for 7 days.',
    es: 'El recorrido del camión por los puntos GPS del ELD, separado en movimiento y paradas. Las paradas de menos de 30 minutos (semáforos, atascos) no se muestran — solo las que cuentan: carga/descarga, repostaje, descanso. Las de 6 horas seguidas o más se marcan como descanso largo. El historial GPS se guarda 7 días.',
    uk: 'Шлях трака за GPS-точками з ELD, розбитий на рух і стоянки. Зупинки коротші за 30 хвилин (світлофори, затори) не показуються — лише помітні: завантаження/вивантаження, заправка, відпочинок. Стоянки від 6 годин поспіль позначені як довгий відпочинок. GPS-історія зберігається 7 днів.',
    ro: 'Traseul camionului după punctele GPS din ELD, împărțit în mers și opriri. Opririle sub 30 de minute (semafoare, ambuteiaje) nu se afișează — doar cele care contează: încărcare/descărcare, alimentare, odihnă. Cele de peste 6 ore la rând sunt marcate ca odihnă lungă. Istoricul GPS se păstrează 7 zile.',
    kk: 'ELD-тен алынған GPS нүктелері бойынша тракттың жолы, қозғалыс пен тұрақтарға бөлінген. 30 минуттан қысқа аялдамалар (бағдаршам, кептеліс) көрсетілмейді — тек байқаларлықтары: тиеу/түсіру, жанармай құю, демалыс. Қатарынан 6 сағаттан асқан тұрақтар ұзақ демалыс деп белгіленеді. GPS тарихы 7 күн сақталады.',
  },
  'trucks.detail.newLoadFromRc': { ru: 'Новый груз из rate con', en: 'New load from rate con', es: 'Nueva carga desde un rate con', uk: 'Новий вантаж із rate con', ro: 'Cursă nouă dintr-un rate con', kk: 'Rate con-нан жаңа жүк' },
  'trucks.detail.newLoadFromRcInfo': {
    ru: 'Перетащи сюда PDF или фото rate confirmation — ИИ распознает его, сразу создаст груз на этот трак, прикрепит документ и покажет, что проверить (detention, lumper, team, низкая ставка, брокер и т.д.). Без ручного заполнения форм.',
    en: 'Drop a PDF or photo of the rate confirmation here — AI reads it, creates a load for this truck right away, attaches the document, and flags what to double-check (detention, lumper, team, a low rate, the broker, etc.). No manual form-filling.',
    es: 'Arrastra aquí el PDF o la foto del rate confirmation — la IA lo lee, crea la carga en este camión, adjunta el documento y muestra qué revisar (detención, lumper, team, tarifa baja, bróker, etc.). Sin rellenar formularios a mano.',
    uk: 'Перетягни сюди PDF або фото rate confirmation — ШІ розпізнає його, одразу створить вантаж на цей трак, прикріпить документ і покаже, що перевірити (detention, lumper, team, низька ставка, брокер тощо). Без ручного заповнення форм.',
    ro: 'Trage aici PDF-ul sau poza rate confirmation — IA îl citește, creează imediat cursa pe acest camion, atașează documentul și arată ce trebuie verificat (detenție, lumper, echipaj, tarif mic, broker etc.). Fără completat formulare manual.',
    kk: 'Осында rate confirmation PDF немесе суретін сүйреңіз — ЖИ оны танып, осы трактқа бірден жүк құрады, құжатты тіркейді және нені тексеру керегін көрсетеді (detention, lumper, team, төмен мөлшерлеме, брокер және т.б.). Форманы қолмен толтырусыз.',
  },
  'trucks.detail.orManually': { ru: 'или вручную →', en: 'or manually →', es: 'o a mano →', uk: 'або вручну →', ro: 'sau manual →', kk: 'немесе қолмен →' },
