  'trucks.detail.needsFixPrefix': { ru: 'Нужно починить:', en: 'Needs fixing:', es: 'Hay que reparar:', uk: 'Треба полагодити:', ro: 'De reparat:', kk: 'Жөндеу керек:' },
  'trucks.detail.needsFixSuffix': { ru: '— см. раздел выше.', en: '— see the section above.', es: '— ver la sección de arriba.', uk: '— див. розділ вище.', ro: '— vezi secțiunea de mai sus.', kk: '— жоғарыдағы бөлімді қараңыз.' },
  'trucks.detail.economics': { ru: 'Экономика трака (для расчёта прибыли)', en: 'Truck economics (for profit calculations)', es: 'Economía del camión (para calcular el beneficio)', uk: 'Економіка трака (для розрахунку прибутку)', ro: 'Economia camionului (pentru calculul profitului)', kk: 'Тракт экономикасы (пайданы есептеу үшін)' },
  'trucks.detail.economicsInfo': {
    ru: 'Настройки, по которым считается прибыль каждого груза: MPG, цена дизеля, оплата водителя, фиксированные расходы, обслуживание, факторинг, диспетч. Заполняется один раз и меняется редко — поэтому спрятано.',
    en: 'The settings each load’s profit is calculated from: MPG, diesel price, driver pay, fixed costs, maintenance, factoring, dispatch. Set once and rarely changed — that’s why it’s tucked away.',
    es: 'Los ajustes con los que se calcula el beneficio de cada carga: MPG, precio del diésel, pago al conductor, gastos fijos, mantenimiento, factoring, despacho. Se rellena una vez y cambia poco — por eso está plegado.',
    uk: 'Налаштування, за якими рахується прибуток кожного вантажу: MPG, ціна дизеля, оплата водія, фіксовані витрати, обслуговування, факторинг, диспетч. Заповнюється один раз і змінюється рідко — тому сховано.',
    ro: 'Setările după care se calculează profitul fiecărei curse: MPG, prețul motorinei, plata șoferului, cheltuielile fixe, întreținerea, factoringul, dispeceratul. Se completează o dată și se schimbă rar — de aceea e ascuns.',
    kk: 'Әр жүктің пайдасы есептелетін баптаулар: MPG, дизель бағасы, жүргізуші төлемі, тұрақты шығындар, қызмет көрсету, факторинг, диспетч. Бір рет толтырылады және сирек өзгереді — сондықтан жасырылған.',
  },

